package com.logiplatform.service;
import com.logiplatform.dto.OperationsDtos.*; import com.logiplatform.model.*; import com.logiplatform.repository.*; import com.logiplatform.tenancy.TenantContext; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class OperationalExceptionService { private final OperationalExceptionRepository repo; private final ShipmentRepository shipments; private final NotificationService notifications; public OperationalExceptionService(OperationalExceptionRepository r,ShipmentRepository s,NotificationService n){repo=r;shipments=s;notifications=n;}
 @Transactional public ExceptionResponse open(ExceptionRequest r){UUID t=TenantContext.getTenantId(); if(r.shipmentId()!=null){Shipment s=shipments.findByIdAndTenantId(r.shipmentId(),t).orElseThrow(()->nf("Shipment not found")); notifications.notify(s.getId(),s.getNotificationEmail(),"Logistics exception: "+s.getReferenceCode(),r.description());} return ExceptionResponse.from(repo.save(new OperationalException(t,r.shipmentId(),r.tripId(),r.vehicleId(),r.type().toUpperCase(),r.severity().toUpperCase(),r.owner(),r.description())));}
 @Transactional(readOnly=true) public List<ExceptionResponse> list(String status){UUID t=TenantContext.getTenantId(); List<OperationalException> xs=(status==null||status.isBlank())?repo.findAllByTenantIdOrderByCreatedAtDesc(t):repo.findAllByTenantIdAndStatusOrderByCreatedAtDesc(t,status.toUpperCase()); return xs.stream().map(ExceptionResponse::from).toList();}
 @Transactional public ExceptionResponse resolve(UUID id,ResolveExceptionRequest r){OperationalException x=repo.findByIdAndTenantId(id,TenantContext.getTenantId()).orElseThrow(()->nf("Exception not found")); x.action(r.actionTaken()); x.resolve(r.resolution()); return ExceptionResponse.from(repo.save(x));}
 private static ResponseStatusException nf(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);} }
